"use client";
// Auto-generated shim: iconsax-react v0.0.8 sets icon defaults via
// `Icon.defaultProps = {...}`, which React 19 no longer honors for function
// components (a real, documented React 19 behavior change) — every icon used
// without an explicit color prop silently rendered with no stroke/fill at all.
// This file re-exports every iconsax-react icon wrapped with the defaults it
// was supposed to have (color="currentColor", size=24, variant="Linear"),
// and is aliased over the bare "iconsax-react" import in next.config.ts, so
// every existing and future `import { X } from "iconsax-react"` anywhere in
// the app is automatically fixed with zero per-file changes.
import * as Iconsax from "iconsax-react-original";
import type { ComponentType } from "react";
import type { IconProps } from "iconsax-react-original";

function withDefaults(Icon: ComponentType<IconProps>): ComponentType<IconProps> {
  function Wrapped(props: IconProps) {
    return <Icon color="currentColor" size={24} variant="Linear" {...props} />;
  }
  Wrapped.displayName = (Icon as { displayName?: string }).displayName || "Icon";
  return Wrapped;
}

